def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0]) if grid else 0

    def inside(r, c):
        return 0 <= r < rows and 0 <= c < cols

    # Validate start and goal positions
    if not (inside(*start) and inside(*goal)):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    # BFS
    q = deque([start])
    parent = {start: None}
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while q:
        cur = q.popleft()
        if cur == goal:
            break
        r, c = cur
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            nxt = (nr, nc)
            if inside(nr, nc) and grid[nr][nc] == '.' and nxt not in parent:
                parent[nxt] = cur
                q.append(nxt)

    if goal not in parent:
        return []

    # Reconstruct path
    path = []
    cur = goal
    while cur is not None:
        path.append(cur)
        cur = parent[cur]
    path.reverse()
    return path
